function estateDistributionRecipients(PDO $pdo,int $building,string $from,string $to):array {
 estateDate($from);estateDate($to);if($from>$to||estateDays($from,$to)>3660)throw new RuntimeException('Verteilzeitraum ungültig.');$q=$pdo->prepare('SELECT id,area_units,label FROM estate_units WHERE building_id=? ORDER BY id LIMIT 201');$q->execute([$building]);$units=$q->fetchAll();if(!$units||count($units)>200)throw new RuntimeException('Vollständige Gebäudeeinheiten1–200 erforderlich.');$byUnit=[];foreach($units as $u)$byUnit[(string)$u['id']]=['id'=>(string)$u['id'],'area_units'=>(int)$u['area_units']];$q=$pdo->prepare('SELECT l.* FROM estate_leases l JOIN estate_units u ON u.id=l.unit_id WHERE u.building_id=? AND l.starts_on<=? AND(l.ends_on IS NULL OR l.ends_on>=?) ORDER BY l.id LIMIT 1001');$q->execute([$building,$to,$from]);$rows=$q->fetchAll();if(count($rows)>1000)throw new RuntimeException('Nutzungslimit.');$occupancies=[];foreach($rows as $r)$occupancies[(string)$r['id']]=['id'=>(string)$r['id'],'unit_id'=>(string)$r['unit_id'],'kind'=>$r['occupancy_kind'],'tenant_id'=>(string)($r['tenant_id']??''),'from'=>$r['starts_on'],'to'=>$r['ends_on']??$to,'billing_modes'=>['operating'=>$r['operating_mode']==='advance'?'settlement':'owner','heating'=>$r['heating_mode']==='advance'?'settlement':'owner']];return estateCalcRecipients($byUnit,$occupancies,$from,$to);
}
